<script setup lang="ts">
import { Circle, Download, Eraser, Redo2, Undo2, Upload, ClipboardCopy } from 'lucide-vue-next'

type Point = { x: number, y: number }
type Stroke = { points: Point[], size: number, erase: boolean, source: 'manual-stroke' }
const Red = Circle
const Blue = Circle
const canvas = ref<HTMLCanvasElement>(); const fileInput = ref<HTMLInputElement>(); const image = ref<HTMLImageElement>(); const source = ref<ImageData>(); const result = ref<ImageData>(); const mask = ref<Uint8Array>(); const strokes = ref<Stroke[]>([]); const redo = ref<Stroke[]>([])
const brush = ref(32); const erase = ref(false); const color = ref<'red' | 'blue'>('red'); const highContrast = ref(false); const processing = ref(false); const progress = ref(0); const compare = ref(false); const divider = ref(0); const agreed = ref(false); const consentOpen = ref(false); const message = ref(''); const active = new Map<number, Point>(); const screenPointers = new Map<number, Point>(); let drawingPointerId: number | null = null; let worker: Worker | null = null
const viewport = reactive({ scale: 1, x: 0, y: 0 }); const fit = ref(1)

function repairFailureMessage(code: string) { if (code === 'insufficient-context') return '\u8bf7\u4fdd\u7559\u9009\u533a\u5468\u56f4\u7684\u80cc\u666f\uff0c\u518d\u8fdb\u884c\u4fee\u590d'; if (code === 'memory-allocation-failed') return '\u56fe\u7247\u8fc7\u5927\uff0c\u8bf7\u7f29\u5c0f\u56fe\u7247\u6216\u51cf\u5c11\u6807\u8bb0\u533a\u57df'; return '\u672c\u5730\u4fee\u590d\u5931\u8d25\uff0c\u8bf7\u91cd\u8bd5' }
watch(processing, active => { if (!active || !worker) return; const currentWorker = worker; currentWorker.addEventListener('message', event => { if (event.data?.type !== 'failed') return; currentWorker.terminate(); if (worker === currentWorker) worker = null; processing.value = false; message.value = repairFailureMessage(event.data.code) }) })
function requireConsent() { const saved = localStorage.getItem('scy-web-image-repair-consent'); consentOpen.value = saved !== '2026-08-02' }
onMounted(requireConsent); onBeforeUnmount(() => worker?.terminate())
function acceptConsent() { if (!agreed.value) return; localStorage.setItem('scy-web-image-repair-consent', '2026-08-02'); consentOpen.value = false }
function point(event: PointerEvent): Point | null { const target = canvas.value; const data = source.value; if (!target || !data) return null; const rect = target.getBoundingClientRect(); return { x: (event.clientX - rect.left - viewport.x) / viewport.scale, y: (event.clientY - rect.top - viewport.y) / viewport.scale } }
function resetViewport() { const target = canvas.value; const data = source.value; if (!target || !data) return; fit.value = Math.min(target.clientWidth / data.width, target.clientHeight / data.height); viewport.scale = fit.value; viewport.x = (target.clientWidth - data.width * fit.value) / 2; viewport.y = (target.clientHeight - data.height * fit.value) / 2 }
function redrawMask() { const data = source.value; if (!data) return; const next = new Uint8Array(data.width * data.height); for (const stroke of strokes.value) for (let i = 1; i < stroke.points.length; i += 1) drawMaskLine(next, data.width, data.height, stroke.points[i - 1]!, stroke.points[i]!, stroke.size, stroke.erase); mask.value = next }
function drawMaskLine(target: Uint8Array, width: number, height: number, first: Point, second: Point, size: number, clear: boolean) { const steps = Math.max(1, Math.ceil(Math.hypot(second.x - first.x, second.y - first.y) / Math.max(1, size / 3))); for (let step = 0; step <= steps; step += 1) { const x = first.x + (second.x - first.x) * step / steps; const y = first.y + (second.y - first.y) * step / steps; const radius = size / 2; for (let py = Math.max(0, Math.floor(y - radius)); py <= Math.min(height - 1, Math.ceil(y + radius)); py += 1) for (let px = Math.max(0, Math.floor(x - radius)); px <= Math.min(width - 1, Math.ceil(x + radius)); px += 1) if (Math.hypot(px - x, py - y) <= radius) target[py * width + px] = clear ? 0 : 255 } }
function draw() { const target = canvas.value; const data = source.value; if (!target || !data) return; const ctx = target.getContext('2d')!; const width = target.clientWidth; const height = target.clientHeight; if (target.width !== width || target.height !== height) { target.width = width; target.height = height; resetViewport() } ctx.clearRect(0, 0, width, height); const buffer = document.createElement('canvas'); buffer.width = data.width; buffer.height = data.height; const bufferCtx = buffer.getContext('2d')!; bufferCtx.putImageData(compare.value && result.value ? result.value : data, 0, 0); ctx.save(); ctx.translate(viewport.x, viewport.y); ctx.scale(viewport.scale, viewport.scale); ctx.drawImage(buffer, 0, 0); if (compare.value && result.value) { bufferCtx.putImageData(data, 0, 0); ctx.save(); ctx.beginPath(); ctx.rect(0, 0, data.width * divider.value / 100, data.height); ctx.clip(); ctx.drawImage(buffer, 0, 0); ctx.restore() } if (!compare.value && mask.value) { ctx.fillStyle = color.value === 'red' ? (highContrast.value ? 'rgba(255,0,0,.72)' : 'rgba(244,80,100,.42)') : (highContrast.value ? 'rgba(0,85,255,.72)' : 'rgba(66,130,255,.42)'); for (let y = 0; y < data.height; y += 1) for (let x = 0; x < data.width; x += 1) if (mask.value[y * data.width + x]) ctx.fillRect(x, y, 1, 1) } ctx.restore(); if (compare.value) { const line = viewport.x + data.width * viewport.scale * divider.value / 100; ctx.fillStyle = '#fff'; ctx.fillRect(line - 1, viewport.y, 2, data.height * viewport.scale) } }
watch([source, result, mask, () => viewport.scale, () => viewport.x, () => viewport.y, color, highContrast, compare, divider], () => nextTick(draw), { deep: true })
watch(source, value => { if (!value) return; result.value = undefined; compare.value = false; divider.value = 0; message.value = ''; drawingPointerId = null; active.clear(); screenPointers.clear() })
function paint(event: PointerEvent) { const previousScreen = screenPointers.get(event.pointerId); const currentScreen = { x: event.clientX, y: event.clientY }; screenPointers.set(event.pointerId, currentScreen); if (event.pointerType === 'touch' && screenPointers.size > 1 && previousScreen) { const other = Array.from(screenPointers.entries()).find(([id]) => id !== event.pointerId)?.[1]; if (other) { const previousDistance = Math.hypot(previousScreen.x - other.x, previousScreen.y - other.y); const nextDistance = Math.hypot(currentScreen.x - other.x, currentScreen.y - other.y); if (previousDistance > 0) viewport.scale = Math.max(fit.value, Math.min(fit.value * 8, viewport.scale * nextDistance / previousDistance)); viewport.x += currentScreen.x - previousScreen.x; viewport.y += currentScreen.y - previousScreen.y; draw() } return } if (drawingPointerId !== event.pointerId) return; const next = point(event); const draft = strokes.value.at(-1); if (!next || !source.value || compare.value || !draft) return; draft.points.push(next); redrawMask(); draw(); active.set(event.pointerId, next) }
function down(event: PointerEvent) { const next = point(event); if (!next) return; screenPointers.set(event.pointerId, { x: event.clientX, y: event.clientY }); if (event.pointerType === 'touch' && active.size > 0) { active.set(event.pointerId, next); canvas.value?.setPointerCapture(event.pointerId); return } if (compare.value) return; active.set(event.pointerId, next); drawingPointerId = event.pointerId; const stroke: Stroke = { points: [next, next], size: brush.value, erase: erase.value, source: 'manual-stroke' }; strokes.value = [...strokes.value, stroke].slice(-100); redo.value = []; canvas.value?.setPointerCapture(event.pointerId) }
function up(event: PointerEvent) { if (drawingPointerId === event.pointerId) drawingPointerId = null; active.delete(event.pointerId); screenPointers.delete(event.pointerId) }
function zoom(event: WheelEvent) { if (!source.value) return; event.preventDefault(); const direction = event.deltaY < 0 ? 1.15 : .87; viewport.scale = Math.max(fit.value, Math.min(fit.value * 8, viewport.scale * direction)); draw() }
function undo() { const value = strokes.value.pop(); if (value) { redo.value.push(value); redrawMask(); draw() } } function redoStroke() { const value = redo.value.pop(); if (value) { strokes.value.push(value); redrawMask(); draw() } }
async function choose(file?: File) { const selected = file || fileInput.value?.files?.[0]; if (!selected) return; const url = URL.createObjectURL(selected); const loaded = new Image(); loaded.onload = () => { let width = loaded.naturalWidth; let height = loaded.naturalHeight; const max = Math.max(width, height); if (max > 4096) { width = Math.round(width * 4096 / max); height = Math.round(height * 4096 / max) } const deviceMemory = Number((navigator as Navigator & { deviceMemory?: number }).deviceMemory || 8); if (max >= 3500 && deviceMemory <= 4 && confirm('这张图片可能占用较多浏览器内存。是否生成 3072 像素工作副本？选择“取消”将继续原尺寸处理。')) { const factor = Math.min(1, 3072 / Math.max(width, height)); width = Math.round(width * factor); height = Math.round(height * factor) } const work = document.createElement('canvas'); work.width = width; work.height = height; work.getContext('2d')!.drawImage(loaded, 0, 0, width, height); image.value = loaded; source.value = work.getContext('2d')!.getImageData(0, 0, width, height); mask.value = new Uint8Array(width * height); result.value = undefined; strokes.value = []; redo.value = []; nextTick(() => { resetViewport(); draw() }); URL.revokeObjectURL(url) }; loaded.src = url }
function area() { const current = mask.value; return current ? Array.from(current).filter(Boolean).length / current.length : 0 }
async function repair() { if (!source.value || !mask.value || processing.value) return; if (!mask.value.some(Boolean)) { message.value = '请先涂抹需要修复的区域'; return } if (area() >= .2 && !confirm('当前标记范围较大，处理可能需要较长时间，是否继续？')) return; processing.value = true; progress.value = 0; message.value = ''; worker?.terminate(); worker = new Worker(new URL('~/workers/image-inpaint.worker.ts', import.meta.url), { type: 'module' }); worker.onmessage = event => { if (event.data.type === 'progress') progress.value = event.data.progress; if (event.data.type === 'complete') { result.value = new ImageData(new Uint8ClampedArray(event.data.pixels), source.value!.width, source.value!.height); processing.value = false; compare.value = true; draw() } }; worker.onerror = () => { processing.value = false; message.value = '本地修复失败，请尝试缩小图片或减少标记区域' }; worker.postMessage({ pixels: source.value.data.buffer.slice(0), mask: mask.value.buffer.slice(0), width: source.value.width, height: source.value.height }) }
function cancel() { worker?.terminate(); worker = null; processing.value = false; message.value = '已取消处理' }
async function blob() { if (!result.value) return null; const output = document.createElement('canvas'); output.width = result.value.width; output.height = result.value.height; output.getContext('2d')!.putImageData(result.value, 0, 0); return new Promise<Blob | null>(resolve => output.toBlob(resolve, 'image/png')) }
async function download() { const value = await blob(); if (!value) return; const link = document.createElement('a'); link.href = URL.createObjectURL(value); link.download = 'image-repair.png'; link.click(); URL.revokeObjectURL(link.href) }
async function copyImage() { const value = await blob(); if (!value || !navigator.clipboard || typeof ClipboardItem === 'undefined') { message.value = '当前浏览器不支持复制图片，请使用下载 PNG'; return } try { await navigator.clipboard.write([new ClipboardItem({ 'image/png': value })]); message.value = '图片已复制到剪贴板' } catch { message.value = '复制失败，请使用下载 PNG' } }
</script>
<template><section class="editor"><input ref="fileInput" class="hidden" type="file" accept="image/*" @change="choose()"><div v-if="!source" class="empty-state panel"><Upload :size="28" /><strong>选择需要处理的图片</strong><button class="button" @click="fileInput?.click()">选择图片</button></div><template v-else><div class="toolbar panel"><button class="icon-button" title="重选图片" @click="fileInput?.click()"><Upload :size="17" /></button><button class="icon-button" :class="{ 'icon-button-active': !erase }" title="画笔" @click="erase = false">笔</button><button class="icon-button" :class="{ 'icon-button-active': erase }" title="橡皮擦" @click="erase = true"><Eraser :size="17" /></button><label>笔刷 <input v-model.number="brush" type="range" min="1" max="100"><output>{{ brush }}</output></label><button class="icon-button" title="撤销" :disabled="!strokes.length" @click="undo"><Undo2 :size="17" /></button><button class="icon-button" title="重做" :disabled="!redo.length" @click="redoStroke"><Redo2 :size="17" /></button><button class="icon-button" title="红色掩膜" @click="color = 'red'"><Red :size="17" /></button><button class="icon-button" title="蓝色掩膜" @click="color = 'blue'"><Blue :size="17" /></button><label><input v-model="highContrast" type="checkbox"> 高对比</label></div><div class="canvas-wrap panel"><canvas ref="canvas" @pointerdown="down" @pointermove="paint" @pointerup="up" @pointercancel="up" @wheel="zoom" /></div><label v-if="compare" class="compare">原图 <input v-model.number="divider" type="range" min="0" max="100"> 修复结果</label><div class="actions"><button class="button" :disabled="processing" @click="repair">{{ processing ? `处理中 ${progress}%` : '去除' }}</button><button v-if="processing" class="button button-secondary" @click="cancel">取消</button><button v-if="result" class="button button-secondary" @click="download"><Download :size="17" />下载 PNG</button><button v-if="result" class="button button-secondary" @click="copyImage"><ClipboardCopy :size="17" />复制图片</button></div><p v-if="message" class="notice">{{ message }}</p></template><div v-if="consentOpen" class="modal"><section class="panel dialog"><h2>使用前请确认</h2><p>仅可处理您拥有版权或授权处理的图片。图片、掩膜和修复结果仅在当前浏览器处理，不会上传。</p><label><input v-model="agreed" type="checkbox"> 我确认拥有图片处理权</label><button class="button" :disabled="!agreed" @click="acceptConsent">同意并继续</button></section></div></section></template>
<style scoped>.editor { display:grid; gap:14px; }.hidden { display:none; }.toolbar,.actions { display:flex; flex-wrap:wrap; align-items:center; gap:8px; padding:12px; }.toolbar label { display:flex; align-items:center; gap:6px; color:var(--muted); font-size:13px; }.toolbar input[type=range] { accent-color:var(--teal); }.toolbar .icon-button:nth-of-type(6) { color:#dc2626; background:#fff1f2; border-color:#fda4af; }.toolbar .icon-button:nth-of-type(7) { color:#2563eb; background:#eff6ff; border-color:#93c5fd; }.toolbar .icon-button:nth-of-type(6):hover { background:#ffe4e6; }.toolbar .icon-button:nth-of-type(7):hover { background:#dbeafe; }.canvas-wrap { height:min(65vh,640px); overflow:hidden; touch-action:none; }.canvas-wrap canvas { display:block; width:100%; height:100%; cursor:crosshair; }.actions { padding:0; }.compare { display:flex; align-items:center; justify-content:center; gap:10px; color:var(--muted); font-size:13px; }.compare input { width:min(420px,60vw); accent-color:var(--teal); }.notice { margin:0; color:var(--muted); font-size:13px; }.modal { position:fixed; z-index:30; inset:0; display:grid; place-items:center; padding:18px; background:rgba(30,45,48,.36); }.dialog { display:grid; width:min(100%,460px); gap:18px; padding:24px; }.dialog h2,.dialog p { margin:0; }.dialog p { color:var(--muted); line-height:1.6; }.dialog label { font-size:14px; }.empty-state { min-height:280px; }</style>
